package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
/** Actual bounds, scroll/touch reach and accessibility labels on synthetic owner. Not TalkBack speech proof. */
public final class Beta995AccessNativeTest extends Instrumentation {
 int checks;Throwable fail;void check(boolean v,String s){checks++;if(!v)throw new AssertionError(s);}void main(Runnable r){runOnMainSync(()->{try{r.run();}catch(Throwable t){fail=t;}});if(fail!=null)throw new AssertionError(fail);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 View named(View v,String label){if(v.isClickable()&&v.getContentDescription()!=null&&v.getContentDescription().toString().equals(label))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=named(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}
 void bounds(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.getLayout()!=null&&t.length()>0){android.text.Layout l=t.getLayout();check(l.getEllipsisCount(l.getLineCount()-1)==0,"No ellipsis: "+t.getText());check(t.getHeight()>=t.getCompoundPaddingTop()+t.getCompoundPaddingBottom()+l.getLineBottom(l.getLineCount()-1),"No vertical text clipping: "+t.getText());}if(v instanceof Button)check(v.getHeight()>=48*v.getResources().getDisplayMetrics().density,"Touch target >=48dp");}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)bounds(((ViewGroup)v).getChildAt(i));}
 @Override public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter.trial")&&TrialDemo.active(c),"Owned virtual demo");String account=SubscriptionStore.accountKey(c);long total=BetaGrowthStore.load(c,account).getLong("total");
 for(Class<?> screen:new Class<?>[]{GrowthActivity.class,BetaCatalogActivity.class,MeterSettingsActivity.class}){Activity a=startActivitySync(new Intent(c,screen).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1000);waitForIdleSync();main(()->bounds(a.findViewById(R.id.dashboard_content)));if(a instanceof GrowthActivity){main(()->((androidx.core.widget.NestedScrollView)a.findViewById(R.id.dashboard_scroll)).fullScroll(View.FOCUS_DOWN));Thread.sleep(400);waitForIdleSync();main(()->{View link=named(a.findViewById(android.R.id.content),BetaCopy.t(a,"share"));android.graphics.Rect rect=new android.graphics.Rect();check(link!=null&&link.getGlobalVisibleRect(rect)&&rect.height()>=48*a.getResources().getDisplayMetrics().density,"Profile action scrolls into tappable view");View bar=a.findViewById(R.id.matte_bottom);int[] xy=new int[2];bar.getLocationOnScreen(xy);check(rect.bottom<=xy[1],"Content stops above bottom navigation");});}main(a::finish);}
 check(BetaGrowthStore.load(c,account).getLong("total")==total,"Bounds/scroll inspection never awards XP");result.putString("stream","Beta 9.9.5 bounds/accessibility: "+checks+" checks passed; actual line layout, touch size, scroll and nav insets; synthetic only.\n");finish(-1,result);
 }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));finish(0,result);}}
}
